/** Canonical JSON with sorted keys, so hashes are stable across writers. Matches the guarantee registry. */
export function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`
  if (value && typeof value === 'object') {
    const obj = value as Record<string, unknown>
    const keys = Object.keys(obj).sort()
    return `{${keys.map((k) => `${JSON.stringify(k)}:${canonical(obj[k])}`).join(',')}}`
  }
  return JSON.stringify(value)
}

const encoder = new TextEncoder()

export async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', encoder.encode(text))
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('')
}

function base64ToBytes(b64: string): Uint8Array<ArrayBuffer> {
  const bin = atob(b64.replace(/\s+/g, ''))
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  return out
}

/** Import an Ed25519 public key from a PEM (SPKI) string. */
export async function importPublicKey(pem: string): Promise<CryptoKey> {
  const body = pem.replace(/-----(BEGIN|END) PUBLIC KEY-----/g, '')
  return crypto.subtle.importKey('spki', base64ToBytes(body), { name: 'Ed25519' }, false, ['verify'])
}

export async function verifyEd25519(key: CryptoKey, text: string, sigB64: string): Promise<boolean> {
  try {
    return await crypto.subtle.verify({ name: 'Ed25519' }, key, base64ToBytes(sigB64), encoder.encode(text))
  } catch {
    return false
  }
}

import { canonical, sha256Hex } from './canonical'

/**
 * A view receipt says what a person was shown: which component, which of your records, and the hash of the exact data
 * drawn. Signed and put in the ledger, it answers the question an approval alone cannot: what did the reviewer see when
 * they decided. Change one value of the data and the hash no longer matches.
 */
export type ViewReceipt = {
  schema: 'orlune.view.v1'
  component: string
  kind: string
  source: string
  /** SHA-256 of the canonical JSON of the data that was drawn. */
  dataHash: string
  /** Who it was shown to. */
  by: string
  shownAt: string
  /** The plan hash the reviewer was looking at, when the view was part of an approval. */
  planHash?: string
}

export type SignedViewReceipt = { receipt: ViewReceipt; sig: string }

export async function createViewReceipt(i: { component: string; kind: string; source: string; data: unknown; by: string; at?: Date; planHash?: string }): Promise<ViewReceipt> {
  return {
    schema: 'orlune.view.v1',
    component: i.component,
    kind: i.kind,
    source: i.source,
    dataHash: await sha256Hex(canonical(i.data)),
    by: i.by,
    shownAt: (i.at ?? new Date()).toISOString(),
    ...(i.planHash ? { planHash: i.planHash } : {}),
  }
}

const enc = new TextEncoder()
const toB64 = (bytes: ArrayBuffer) => btoa(String.fromCharCode(...new Uint8Array(bytes)))
const fromB64 = (b64: string) => Uint8Array.from(atob(b64.replace(/\s+/g, '')), (c) => c.charCodeAt(0))

/** Import an Ed25519 private key from a PKCS8 PEM. Signing belongs on your server, never in the page a reviewer opens. */
export async function importPrivateKey(pem: string): Promise<CryptoKey> {
  const body = pem.replace(/-----(BEGIN|END) PRIVATE KEY-----/g, '')
  return crypto.subtle.importKey('pkcs8', fromB64(body), { name: 'Ed25519' }, false, ['sign'])
}

/** Sign a receipt with an Ed25519 key. The signature covers the canonical JSON of the receipt. */
export async function signViewReceipt(receipt: ViewReceipt, key: CryptoKey): Promise<SignedViewReceipt> {
  return { receipt, sig: toB64(await crypto.subtle.sign({ name: 'Ed25519' }, key, enc.encode(canonical(receipt)))) }
}

export type ViewVerdict = {
  /** The signature is valid for this receipt and this key. */
  signatureValid: boolean
  /** Only set when you pass the data as it is now: whether it is the same data the reviewer was shown. */
  dataMatches?: boolean
}

/** Checks a signed receipt offline. Pass `data` (what your store holds now) to learn whether it still matches what was shown. */
export async function verifyViewReceipt(signed: SignedViewReceipt, publicKey: CryptoKey, data?: unknown): Promise<ViewVerdict> {
  let signatureValid = false
  try {
    signatureValid = await crypto.subtle.verify({ name: 'Ed25519' }, publicKey, fromB64(signed.sig), enc.encode(canonical(signed.receipt)))
  } catch {
    signatureValid = false
  }
  return data === undefined ? { signatureValid } : { signatureValid, dataMatches: (await sha256Hex(canonical(data))) === signed.receipt.dataHash }
}

/** The hash of what a reviewer sees in an approval, so a decision can say it was made on exactly this. */
export const viewDigest = (shown: unknown): Promise<string> => sha256Hex(canonical(shown))

import { canonical, importPublicKey, sha256Hex, verifyEd25519 } from './canonical'
import type { GuaranteeResult, LedgerEvent, RecordBundle, VerifiedEvent, VerifyResult } from './types'

const hours = (a: string, b: string) => (new Date(b).getTime() - new Date(a).getTime()) / 36e5

export type VerifyOptions = {
  /** The moment to judge open deadlines against. Defaults to now. Pass it to make a result reproducible. */
  now?: Date
  /** Fingerprints of keys you recognise, from `keyFingerprint`. With it the result says whether each signer is one of them. */
  trustedKeys?: string[]
}

/** The first 16 hex characters of the SHA-256 of a public key's PEM with its white space removed. Compare these, not the PEM text. */
export async function keyFingerprint(pem: string): Promise<string> {
  return (await sha256Hex(pem.replace(/\s+/g, ''))).slice(0, 16)
}

/**
 * Verifies a record offline: manifest hash and both signatures, the hash-chained signed ledger, and the
 * deadline rules. A breach counts as honored only when a matching remedy event exists. The result is the
 * only thing the record components trust, so it must come from here and never from model output.
 */
export async function verifyRecord(record: RecordBundle, options: VerifyOptions = {}): Promise<VerifyResult> {
  const now = (options.now ?? new Date()).toISOString()
  const problems: string[] = []
  const { manifest, signatures, ledger, publicKeys } = record

  const manifestSha256 = await sha256Hex(canonical(manifest))
  if (signatures.manifestSha256 !== manifestSha256) problems.push('Manifest has been modified since signing (hash mismatch).')

  const keys = new Map<string, CryptoKey>()
  for (const [party, pem] of Object.entries(publicKeys)) {
    try {
      keys.set(party, await importPublicKey(pem))
    } catch {
      problems.push(`Public key for ${party} could not be read.`)
    }
  }

  const required = Object.values(manifest.parties ?? {}).length ? Object.values(manifest.parties ?? {}) : Object.keys(publicKeys)
  const sigRows: VerifyResult['signatures'] = []
  for (const party of required) {
    const entry = signatures.signatures[party]
    const key = keys.get(party)
    const keyId = publicKeys[party] ? await keyFingerprint(publicKeys[party]!) : undefined
    const trusted = options.trustedKeys ? keyId !== undefined && options.trustedKeys.map((k) => k.toLowerCase()).includes(keyId) : undefined
    if (!entry) {
      problems.push(`Manifest is not signed by ${party}.`)
      sigRows.push({ party, valid: false, keyId, trusted })
    } else if (!key || !(await verifyEd25519(key, signatures.manifestSha256, entry.sig))) {
      problems.push(`${party} signature on the manifest is invalid.`)
      sigRows.push({ party, valid: false, signedAt: entry.signedAt, keyId, trusted })
    } else {
      sigRows.push({ party, valid: true, signedAt: entry.signedAt, keyId, trusted })
    }
  }

  const events: VerifiedEvent[] = []
  let prev = 'genesis'
  let intact = true
  for (const entry of ledger) {
    const { sig, ...body } = entry
    const chainValid = body.prev === prev
    const key = keys.get(body.by)
    const signatureValid = key ? await verifyEd25519(key, canonical(body), sig) : false
    if (!chainValid) {
      intact = false
      problems.push(`Ledger broken at event #${body.seq}: chain hash mismatch (tampering or deletion).`)
    }
    if (!signatureValid) {
      intact = false
      problems.push(`Event #${body.seq} (${body.type}) signature is invalid for ${body.by}.`)
    }
    const hash = await sha256Hex(canonical(entry))
    events.push({
      seq: body.seq,
      type: body.type,
      at: body.at,
      by: body.by,
      label: body.label,
      result: body.result,
      ref: body.ref,
      guarantee: body.guarantee,
      hash: hash.slice(0, 12),
      signatureValid,
      chainValid,
    })
    prev = hash
  }

  const guarantees = judgeGuarantees(manifest.guarantees.map((g) => g.id), manifest, ledger, now)
  const unremedied = guarantees.some((g) => g.status === 'breached' && g.remedyOutstanding)

  return {
    ok: problems.length === 0 && !unremedied,
    engagement: manifest.engagement,
    manifestSha256,
    signatures: sigRows,
    trust: !options.trustedKeys ? 'not-checked' : sigRows.length > 0 && sigRows.every((r) => r.trusted) ? 'trusted' : 'valid-unknown-signer',
    ledger: { events: ledger.length, intact },
    guarantees,
    events,
    problems,
    verifiedAt: now,
  }
}

function judgeGuarantees(ids: string[], manifest: RecordBundle['manifest'], ledger: LedgerEvent[], now: string): GuaranteeResult[] {
  const remedies = ledger.filter((e) => e.type === 'remedy')
  const remedied = (id: string, ref?: number) => remedies.some((r) => r.guarantee === id && (ref === undefined || r.ref === ref))
  const deadline = (id: string, fallback: number) => manifest.guarantees.find((g) => g.id === id)?.deadlineHours ?? fallback
  const out: GuaranteeResult[] = []
  const push = (id: string, status: 'honored' | 'pending' | 'breached', detail: string, ref?: number) => {
    const fixed = status === 'breached' && remedied(id, ref)
    out.push({ id, status: fixed ? 'remedied' : status, detail, remedyOutstanding: status === 'breached' && !fixed })
  }

  for (const id of ids) {
    if (id === 'G1-CRITERIA') {
      const criteria = ledger.find((e) => e.type === 'criteria_signed')
      const launch = ledger.find((e) => e.type === 'launch')
      if (launch && !criteria) push(id, 'breached', 'launch without signed criteria')
      else if (launch && criteria && hours(criteria.at, launch.at) < 0) push(id, 'breached', 'criteria signed after launch')
      else push(id, launch ? 'honored' : 'pending', launch ? 'criteria signed before launch' : 'no launch yet')
    } else if (id === 'G2-RETEST-48H') {
      const limit = deadline(id, 48)
      for (const rel of ledger.filter((e) => e.type === 'model_release')) {
        const retest = ledger.find((e) => e.type === 'retest' && e.ref === rel.seq)
        if (!retest) {
          const overdue = hours(rel.at, now) > limit
          push(id, overdue ? 'breached' : 'pending', `release #${rel.seq} ${overdue ? 'has no re-test' : 'awaiting re-test'}`, rel.seq)
        } else {
          const h = hours(rel.at, retest.at)
          push(id, h <= limit ? 'honored' : 'breached', `release #${rel.seq} re-tested in ${h.toFixed(1)}h, ${retest.result ?? 'no result'}`, rel.seq)
        }
      }
    } else if (id === 'G3-ROOTCAUSE-24H') {
      const limit = deadline(id, 24)
      for (const inc of ledger.filter((e) => e.type === 'incident')) {
        const rc = ledger.find((e) => e.type === 'root_cause' && e.ref === inc.seq)
        if (!rc) {
          const overdue = hours(inc.at, now) > limit
          push(id, overdue ? 'breached' : 'pending', `incident #${inc.seq} ${overdue ? 'has no root cause' : 'awaiting root cause'}`, inc.seq)
        } else {
          const h = hours(inc.at, rc.at)
          push(id, h <= limit ? 'honored' : 'breached', `incident #${inc.seq} root cause in ${h.toFixed(1)}h`, inc.seq)
        }
      }
    } else if (id === 'G4-RECORD-OWNED') {
      push(id, 'honored', 'this result was computed offline from the record and public keys alone')
    }
  }
  return out
}
